// Word forms on the word card: a verb's whole table (past, present, command) with the easy trick for each
// person, and a noun's forms as the Quran uses them. Data: data/forms/ROOT.json, built by tools/build_forms.py
// (generated by rules, checked against every verb in the Quran; forms the Quran uses are marked and counted).

const esc = (s) => String(s ?? "").replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c]);
const FORMS = new Map();
export const formsOf = (key) => {
  if (!FORMS.has(key)) {
    FORMS.set(key, fetch(`data/forms/${encodeURIComponent(key)}.json`).then((r) => (r.ok ? r.json() : {})).catch(() => { FORMS.delete(key); return {}; }));
  }
  return FORMS.get(key);
};

const PERSONS = ["3MS", "3FS", "3MD", "3FD", "3MP", "3FP", "2MS", "2FS", "2D", "2MP", "2FP", "1S", "1P"];
const CMD = ["2MS", "2FS", "2D", "2MP", "2FP"];
// who does it, in English, Urdu and Hindi
const WHO = {
  "3MS": ["he", "وہ (مرد)", "वह (मर्द)"], "3FS": ["she", "وہ (عورت)", "वह (औरत)"],
  "3MD": ["they two (m)", "وہ دو (مرد)", "वे दो (मर्द)"], "3FD": ["they two (f)", "وہ دو (عورتیں)", "वे दो (औरतें)"],
  "3MP": ["they (m)", "وہ سب (مرد)", "वे सब (मर्द)"], "3FP": ["they (f)", "وہ سب (عورتیں)", "वे सब (औरतें)"],
  "2MS": ["you (m)", "تو (مرد)", "तू (मर्द)"], "2FS": ["you (f)", "تو (عورت)", "तू (औरत)"],
  "2D": ["you two", "تم دو", "तुम दो"], "2MP": ["you all (m)", "تم سب (مرد)", "तुम सब (मर्द)"],
  "2FP": ["you all (f)", "تم سب (عورتیں)", "तुम सब (औरतें)"], "1S": ["I", "میں", "मैं"], "1P": ["we", "ہم", "हम"],
};
// The trick for each person: the shape to look for (prefix … ending, read right to left) and a short hint.
// Present is read from "he" (يـ), past from "he" (the bare form), command from "you" in the present.
const TRICK = {
  pres: {
    "3MS": ["يـ … ـُ", "starts with يـ"], "3FS": ["تـ … ـُ", "يـ becomes تـ"], "3MD": ["يـ … ـَانِ", "two: add ـَانِ"],
    "3FD": ["تـ … ـَانِ", "تـ and ـَانِ"], "3MP": ["يـ … ـُونَ", "many: add ـُونَ"], "3FP": ["يـ … ـْنَ", "women: add ـْنَ"],
    "2MS": ["تـ … ـُ", "same as she"], "2FS": ["تـ … ـِينَ", "add ـِينَ"], "2D": ["تـ … ـَانِ", "same as they two (f)"],
    "2MP": ["تـ … ـُونَ", "they (m) with تـ instead of يـ"], "2FP": ["تـ … ـْنَ", "they (f) with تـ"],
    "1S": ["أ … ـُ", "starts with أ"], "1P": ["نـ … ـُ", "starts with نـ"],
  },
  past: {
    "3MS": ["… ـَ", "the bare form"], "3FS": ["… ـَتْ", "add ـَتْ"], "3MD": ["… ـَا", "add ـَا"], "3FD": ["… ـَتَا", "add ـَتَا"],
    "3MP": ["… ـُوا", "add ـُوا"], "3FP": ["… ـْنَ", "add ـْنَ"], "2MS": ["… ـْتَ", "add ـْتَ"], "2FS": ["… ـْتِ", "add ـْتِ"],
    "2D": ["… ـْتُمَا", "add ـْتُمَا"], "2MP": ["… ـْتُمْ", "add ـْتُمْ"], "2FP": ["… ـْتُنَّ", "add ـْتُنَّ"],
    "1S": ["… ـْتُ", "add ـْتُ"], "1P": ["… ـْنَا", "add ـْنَا"],
  },
  cmd: {
    "2MS": ["… ـْ", "you (present): drop تـ, end silent"], "2FS": ["… ـِي", "drop تـ and the ن"], "2D": ["… ـَا", "drop تـ and the ن"],
    "2MP": ["… ـُوا", "drop تـ and the ن"], "2FP": ["… ـْنَ", "drop تـ"],
  },
};
const TENSES = [["pres", "Present: does, is doing, will do", PERSONS], ["past", "Past: did", PERSONS], ["cmd", "Command: do!", CMD]];
// Forms outside the table, as the Quran uses them
const MOODS = {
  SUBJ: "after أَنْ، لَنْ، كَيْ: ـُ → ـَ, and ـونَ / ـينَ / ـانِ lose their ن",
  JUS: "after لَمْ، لا (don't), لِـ (let), or in if-sentences: the end goes silent, and ـونَ / ـينَ / ـانِ lose their ن",
  PASS: "passive: was done, is done",
};
const REL = { ACT_PCPL: "the one who does it", PASS_PCPL: "the one it is done to", VN: "the doing (verbal noun)" };
const NUM = {
  MS: "one (m)", FS: "one (f)", MD: "two (m)", FD: "two (f)", MP: "many (m)", FP: "many (f)", M: "masculine", F: "feminine",
  D: "two", P: "many",
};
const CASE = { NOM: "doer / subject: ends ـُ ـٌ ـونَ ـانِ", ACC: "object: ends ـَ ـً ـِينَ ـَيْنِ", GEN: "after a preposition or 'of': ends ـِ ـٍ ـِينَ ـَيْنِ" };

const MARKS = /[\u0610-\u061A\u064B-\u065F\u0670\u06D6-\u06ED]/;
const letters = (t) => [...t].reduce((a, c) => { if (MARKS.test(c) && a.length) a[a.length - 1] += c; else a.push(c); return a; }, []);
// the starts and ends that differ from the base are coloured; the shared stem stays plain
function hl(form, base) {
  if (!base || form === base) return esc(form);
  const f = letters(form), b = letters(base), bare = (x) => x.replace(new RegExp(MARKS.source, "g"), "");
  // find the base's longest run of letters that also appears in the form: that is the stem
  let best = [0, 0, 0];
  for (let s = 0; s < f.length; s++) for (let t = 0; t < b.length; t++) {
    let n = 0;
    while (s + n < f.length && t + n < b.length && bare(f[s + n]) === bare(b[t + n])) n++;
    if (n > best[2]) best = [s, t, n];
  }
  const [s, , n] = best;
  if (n < 2) return esc(form);
  const pre = f.slice(0, s).join(""), mid = f.slice(s, s + n).join(""), post = f.slice(s + n).join("");
  return `${pre ? `<b>${esc(pre)}</b>` : ""}${esc(mid)}${post ? `<b>${esc(post)}</b>` : ""}`;
}

const who = (p, langs) => {
  const [en, ur, hi] = WHO[p];
  return `${esc(en)}${langs.includes("ur") ? `<span class="ur">${esc(ur)}</span>` : ""}${langs.includes("hi") ? `<span lang="hi">${esc(hi)}</span>` : ""}`;
};
const where = (loc) => { const [s, a] = String(loc).split(":"); return `#/s/${s}/${a}`; };
const quran = (q) => (q ? `<a class="qtag" href="${where(q[1])}" title="Used ${q[0]} times in the Quran; tap to see one">Quran ×${q[0]}</a>` : "");

function verbHTML(e, w, langs) {
  const mine = (w.g || "").split(".").slice(0, 2).join(".");
  // the tapped word's tense comes first
  const tenses = [...TENSES].sort((a, b) => (b[0] === mine.split(".")[0]) - (a[0] === mine.split(".")[0]));
  const tables = tenses.map(([k, title, ps]) => {
    const forms = e[k] || {};
    if (!ps.some((p) => forms[p])) return "";
    const base = k === "cmd" ? (e.pres || {})["2MS"] : forms["3MS"];
    const rows = ps.filter((p) => forms[p]).map((p) => {
      const q = (e.q || {})[`${k}.${p}`];
      return `<tr class="${mine === `${k}.${p}` ? "me" : ""}${q ? " inq" : ""}"><td class="pp">${who(p, langs)}</td>
        <td class="ar f">${hl(forms[p], k === "cmd" ? null : base)}</td><td class="tr"><span class="ar pat" dir="rtl">${esc(TRICK[k][p][0])}</span>${TRICK[k][p][1].startsWith("add ") ? "" : `<span>${esc(TRICK[k][p][1])}</span>`}${quran(q)}</td></tr>`;
    }).join("");
    return `<div class="ftitle">${title}</div><table class="ftab">${rows}</table>`;
  }).join("");
  const extra = (e.qx || []).map(([t, tag, n, loc]) => {
    const [k, p, mood] = tag.split(".");
    if (mood === "Q") return ""; // Quran words the corpus tags oddly or splits (see tools/forms_report.txt): not shown
    const note = MOODS[mood] || "";
    return `<li><span class="ar">${esc(t)}</span> <span class="note">${esc(WHO[p] ? WHO[p][0] : p)}${k === "past" ? ", past" : ""}${note ? ` · ${esc(note)}` : ""}</span> <a class="qtag" href="${where(loc)}">×${n}</a></li>`;
  }).join("");
  const rel = (e.rel || []).map(([t, kind, n, loc]) => `<li><span class="ar">${esc(t)}</span> <span class="note">${esc(REL[kind] || kind)}</span> <a class="qtag" href="${where(loc)}">×${n}</a></li>`).join("");
  return `${e.check ? `<p class="note">Some forms of this verb are irregular; the table shows the regular forms.</p>` : ""}
    ${tables}
    ${extra ? `<div class="ftitle">Also in the Quran</div><ul class="flist">${extra}</ul>` : ""}
    ${rel ? `<div class="ftitle">Nouns from this verb</div><ul class="flist">${rel}</ul>` : ""}`;
}

function nounHTML(e, w) {
  const mine = w.t;
  const groups = {};
  for (const [t, num, al, cs, n, locs] of e.forms || []) (groups[num || ""] ||= []).push({ t, al, cs, n, loc: (locs || [])[0] });
  const order = ["MS", "FS", "M", "F", "MD", "FD", "D", "MP", "FP", "P", ""];
  const body = order.filter((k) => groups[k]).map((k) => `<div class="ftitle">${esc(NUM[k] || "other")}</div><ul class="flist">${groups[k]
    .sort((a, b) => b.n - a.n).slice(0, 8)
    .map((x) => `<li class="${mine.endsWith(x.t) ? "me" : ""}"><span class="ar">${esc(x.t)}</span> <span class="note">${x.al ? "with ال: the · " : ""}${esc((CASE[x.cs] || "").split(":")[0])}</span>${x.loc ? ` <a class="qtag" href="${where(x.loc)}">×${x.n}</a>` : ""}</li>`).join("")}</ul>`).join("");
  return `${body}
    <div class="ftitle">The tricks</div>
    <ul class="flist tricks"><li><span class="ar">ال</span> = the</li>
      <li>${esc(CASE.NOM)}</li><li>${esc(CASE.ACC)}</li><li>${esc(CASE.GEN)}</li>
      <li>two: ـَانِ (doer) / ـَيْنِ (other places)</li><li>many men: ـُونَ / ـِينَ · many women or things: ـَات</li></ul>`;
}

// The section's body for the word w (null when there is nothing to show)
export function formsHTML(d, w, langs) {
  const e = d && d[w.l];
  if (!e) return null;
  if (e.pos === "V") return verbHTML(e, w, langs);
  if (e.forms && e.forms.length) return nounHTML(e, w);
  return null;
}

// ---------- Form Switch quiz ----------
// A question turns the Quran word's form (tense and person) into another form of the same verb, with four
// options from the verb's own table. Only verbs whose table is fully regular (no check flag) are asked.
const TENSE_NAME = { pres: ["present", "حال", "वर्तमान"], past: ["past", "ماضی", "भूतकाल"], cmd: ["command", "امر", "आदेश"] };
const LI = { en: 0, ur: 1, hi: 2 };
export const formLabel = (k, p, lang = "en") => `${WHO[p][LI[lang] ?? 0]} · ${TENSE_NAME[k][LI[lang] ?? 0]}`;
export const formHL = hl;
export const trickOf = (k, p) => TRICK[k][p];
// the tense and person of a Quran word, when the quiz can use it: "pres.3MP" (moods are fine, passive is not)
export function switchFrom(e, g) {
  if (!e || e.pos !== "V" || e.check || !g) return null;
  const [k, p, x] = g.split(".");
  if (x === "PASS" || !TRICK[k] || !WHO[p] || !(e[k] || {})[p]) return null;
  return { k, p, t: e[k][p] };
}
const shuffle = (a) => a.sort(() => Math.random() - 0.5);
export function switchQuestion(e, from) {
  const cells = (k) => (k === "cmd" ? CMD : PERSONS).filter((p) => (e[k] || {})[p]).map((p) => ({ k, p, t: e[k][p] }));
  const same = cells(from.k).filter((c) => c.t !== from.t);
  const cross = ["pres", "past", "cmd"].filter((k) => k !== from.k).flatMap(cells).filter((c) => c.t !== from.t);
  // mostly change the person within the tense, sometimes the tense
  const pick = (l) => l[Math.floor(Math.random() * l.length)];
  const sameP = cross.filter((c) => c.p === from.p);
  const to = (Math.random() < 0.7 && same.length) || !cross.length ? pick(same) : pick(sameP.length ? sameP : cross);
  if (!to) return null;
  // wrong options: other cells of the target's tense first (so the person ending decides), then any
  const seen = new Set([to.t]), opts = [to];
  for (const c of [...shuffle(cells(to.k)), ...shuffle([...same, ...cross])]) {
    if (opts.length === 4) break;
    if (!seen.has(c.t)) { seen.add(c.t); opts.push(c); }
  }
  return opts.length < 3 ? null : { from, to, opts: shuffle(opts) };
}
